def bestsub(t,kmax=4):
    out=[]
    for k in range(1,kmax+1):
        best=0;bb=None
        for S in itertools.combinations(range(10),k):
            v=(bits[:,S]*(1<<np.arange(k))).sum(1)
            c=np.bincount(v*8+t,minlength=(2**k)*8).reshape(-1,8)
            p=c.max(1).sum()/len(t)
            if p>best: best=p;bb=S
        out.append((k,round(float(best),3)))
    return out
for s in range(4):
    print('bits',s,bestsub(T[s][mask]),'shuf',bestsub(rng.permutation(T[s][mask])))
# neighbour agreement
for s in range(4):
    res=[]
    for da in range(0,6):
        for db in range(0,6):
            if da==0 and db==0: continue
            m=mask[:32-da,:32-db]&mask[da:,db:]
            x=T[s][:32-da,:32-db][m];y=T[s][da:,db:][m]
            z=(np.mean(x==y)-0.125)/np.sqrt(.109/m.sum())
            res.append((round(float(z),1),da,db))
    res.sort(reverse=True); print('nbr',s,res[:3],res[-1])
