import numpy as np
T=np.load('T.npy'); mask=T[0]>=0
rng=np.random.default_rng(2)
def spec(t):
    # one-hot per class, missing -> 0, centred on observed
    out=[]
    for c in range(8):
        M=np.where(mask,(t==c)-0.125,0.0)
        out.append(np.linalg.svd(M,compute_uv=False)[:3])
    return np.array(out)
for s in range(4):
    r=spec(T[s]); ctrl=[]
    for _ in range(30):
        t=T[s].copy(); t[mask]=rng.permutation(t[mask]); ctrl.append(spec(t).max())
    print('svd',s,'top',round(float(r.max()),3),'ctrl mean',round(float(np.mean(ctrl)),3),'ctrl max',round(float(np.max(ctrl)),3))
# cross-skill contingency chi2 vs permutation
def chi(x,y):
    C=np.bincount(x*8+y,minlength=64).reshape(8,8).astype(float); E=C.sum(1,keepdims=True)*C.sum(0,keepdims=True)/C.sum()
    return ((C-E)**2/E).sum()
for i in range(4):
    for j in range(i+1,4):
        x,y=T[i][mask],T[j][mask]; c=chi(x,y); ctrl=[chi(x,rng.permutation(y)) for _ in range(300)]
        print('chi',i,j,round(c,1),'ctrl mean',round(np.mean(ctrl),1),'p',round(np.mean(np.array(ctrl)>=c),3))
# row / column marginal dependence
for s in range(4):
    t=T[s][mask]; A,B=np.meshgrid(np.arange(32),np.arange(32),indexing='ij'); a,b=A[mask],B[mask]
    ca=chi2=0
    def chi2d(u,t):
        C=np.bincount(u*8+t,minlength=256).reshape(32,8).astype(float);E=C.sum(1,keepdims=True)*C.sum(0,keepdims=True)/C.sum();return ((C-E)**2/np.maximum(E,1e-9)).sum()
    ra,rb=chi2d(a,t),chi2d(b,t); ctrl=[chi2d(a,rng.permutation(t)) for _ in range(200)]
    print('marg',s,'a',round(ra,1),'b',round(rb,1),'ctrl',round(np.mean(ctrl),1),'sd',round(np.std(ctrl),1))
